// Package gen turns a resolved cluster model into deployment files: fabric compose,
// Traefik routes, Postgres init SQL, Tempo/Grafana config, per-app compose stacks,
// core build contexts and Kubernetes manifests.
package gen

import (
	"fmt"
	"strings"

	"axon/internal/descriptor"
	"axon/internal/envcfg"
)

// Header marks generated files.
func Header(comment, source string) string {
	return fmt.Sprintf("%s GENERATED by axon from %s — do not edit by hand; run `axon cluster generate`.\n", comment, source)
}

// PG describes how workloads reach Postgres.
type PG struct {
	Host     string
	Port     int
	User     string
	Password string // literal or "${POSTGRES_PASSWORD}" / "$(POSTGRES_PASSWORD)"
}

// URL returns a DATABASE_URL for db.
func (p PG) URL(db string) string {
	return fmt.Sprintf("postgres://%s:%s@%s:%d/%s?sslmode=disable", p.User, p.Password, p.Host, p.Port, db)
}

// Input is everything generation needs.
type Input struct {
	M      *descriptor.Model
	Env    *envcfg.Env
	Ov     *envcfg.Overrides
	Target string // docker | k8s
	PG     PG
	// Images maps an image repo (no tag) to the tag to deploy (content hash);
	// unset repos deploy ":latest".
	Tags map[string]string
}

// Source is the descriptor path relative to the controller dir.
func (in *Input) Source() string {
	return in.M.L.Infra + "/" + in.M.L.File
}

// Image returns repo:tag for a built image.
func (in *Input) Image(repo string) string {
	if t, ok := in.Tags[repo]; ok && t != "" {
		return repo + ":" + t
	}
	return repo + ":latest"
}

// ResolveRef maps an image reference that axon itself builds ("repo:latest")
// to its content-hash tag, and applies [images] substitutions.
func (in *Input) ResolveRef(ref string) string {
	ref = in.subst(ref)
	repo := ref
	if i := strings.LastIndex(ref, ":"); i > strings.LastIndex(ref, "/") {
		repo = ref[:i]
	}
	if t, ok := in.Tags[repo]; ok && t != "" && !strings.Contains(ref, "@") {
		return repo + ":" + t
	}
	return ref
}

func (in *Input) subst(img string) string {
	if in.Ov != nil {
		if v, ok := in.Ov.Images[img]; ok && v != "" {
			return v
		}
	}
	return in.M.SubstImage(img)
}

// Var renders a reference to a secret value. Generated env always uses "${X}":
// compose interpolates it from axon's process environment (never a file), and
// the Kubernetes renderer turns it into a secretKeyRef.
func (in *Input) Var(name string) string { return "${" + name + "}" }

func (in *Input) tracing() bool { return in.M.C.Fabric.Tracing != nil }

func (in *Input) otel(env map[string]string, service string, sampler bool) {
	if !in.tracing() {
		return
	}
	env["OTEL_EXPORTER_OTLP_ENDPOINT"] = "http://tempo:4317"
	env["OTEL_SERVICE_NAME"] = service
	if sampler {
		env["OTEL_TRACES_SAMPLER"] = "parentbased_always_on"
	}
}

func (in *Input) temporalNS() string {
	if t := in.M.C.Fabric.Temporal; t != nil && t.Namespace != "" {
		return t.Namespace
	}
	return "default"
}

// iamLoginBase returns http://<iam host>.<domain>:<http>/m/<iam token>/oidc.
func (in *Input) iamLoginBase() string {
	c := in.M.C
	iam := c.IAMApp()
	tok := c.IAMToken()
	if iam == nil || iam.Host == "" || tok == "" {
		return ""
	}
	return c.FrontDoor(iam.Host) + "/m/" + tok + "/oidc"
}

// userEnv layers [app.env] then per-env overrides (later wins).
func (in *Input) userEnv(env map[string]string, app string) {
	if a := in.M.C.App(app); a != nil {
		for k, v := range a.Env {
			env[k] = v
		}
	}
	if in.Ov != nil {
		for k, v := range in.Ov.AppEnv[app] {
			env[k] = v
		}
	}
}

// CoreEnv is the environment of a cored app's core host.
func (in *Input) CoreEnv(a *descriptor.AppModel) map[string]string {
	c := in.M.C
	env := map[string]string{}
	if iam := c.Fabric.IAM; iam != nil {
		env["MYCEL_IAM_ISSUER"] = iam.Issuer
		env["MYCEL_IAM_AUDIENCE"] = iam.Audience
		env["MYCEL_IAM_URL"] = iam.Backend
	}
	if a.Decl.Kind != "iam" {
		env["MYCEL_GATE"] = "1"
		if base := in.iamLoginBase(); base != "" {
			env["MYCEL_LOGIN_URL"] = base + "/login"
			env["MYCEL_LOGOUT_URL"] = base + "/logout"
		}
	}
	in.otel(env, a.Decl.Host+"-core", true)
	in.userEnv(env, a.Decl.Name)
	return env
}

// ModuleEnv is the environment of one module server.
func (in *Input) ModuleEnv(a *descriptor.AppModel, mod *descriptor.Module) map[string]string {
	c := in.M.C
	env := map[string]string{
		"MYCEL_LISTEN":  "0.0.0.0:7373",
		"MYCEL_KPI_URL": c.KPIBackend(),
	}
	if mod.DB && a.Decl.DB != "" {
		env["DATABASE_URL"] = in.PG.URL(a.Decl.DB)
	}
	in.otel(env, a.Decl.Host+"-"+mod.Token, true)
	if c.Fabric.Temporal != nil {
		env["TEMPORAL_HOSTPORT"] = "temporal:7233"
		env["TEMPORAL_NAMESPACE"] = in.temporalNS()
	}
	if mod.Token == strings.SplitN(c.KPIBackend(), ":", 2)[0] && c.Fabric.Clickhouse != nil {
		ch := c.Fabric.Clickhouse
		db := ch.Database
		if db == "" {
			db = in.M.L.Runtime() + "_kpi"
		}
		env["CLICKHOUSE_DSN"] = fmt.Sprintf("clickhouse://%s:%s@clickhouse:9000/%s", in.chUser("writer"), in.Var(in.chPassVar("WRITER")), db)
		env["CLICKHOUSE_READ_DSN"] = fmt.Sprintf("clickhouse://%s:%s@clickhouse:9000/%s", in.chUser("reader"), in.Var(in.chPassVar("READER")), db)
		env["CLICKHOUSE_DATABASE"] = db
	}
	if a.Decl.Kind == "iam" && mod.Token == c.IAMToken() {
		if iam := c.Fabric.IAM; iam != nil {
			env["MYCEL_IAM_ISSUER"] = iam.Issuer
			env["MYCEL_IAM_AUDIENCE"] = iam.Audience
		}
		env["MYCEL_IAM_SIGNING_KEY"] = in.Var("IAM_SIGNING_KEY")
		env["MYCEL_SESSION_COOKIE_DOMAIN"] = c.DomainOrDefault()
		if kc := c.Fabric.Keycloak; kc != nil {
			env["OIDC_ISSUER"] = c.FrontDoor("keycloak") + "/realms/" + kc.Realm
			env["OIDC_CLIENT_ID"] = kc.Client
			env["OIDC_CLIENT_SECRET"] = in.Var("OIDC_CLIENT_SECRET")
			env["OIDC_REDIRECT_URL"] = c.FrontDoor(a.Decl.Host) + "/m/" + mod.Token + "/oidc/callback"
		}
	}
	if mod.Token == "clc" || mod.Token == "console" {
		var targets []string
		for _, o := range in.M.Apps {
			if o.Decl.Cored() {
				targets = append(targets, o.Decl.Host+"-core:9080")
			}
		}
		env["MYCEL_CONSOLE_TARGETS"] = strings.Join(targets, ",")
		if kc := c.Fabric.Keycloak; kc != nil {
			env["MYCEL_CONSOLE_REALM"] = kc.Realm
		}
		if tr := c.Fabric.Tracing; tr != nil && tr.GrafanaPort > 0 {
			env["MYCEL_CONSOLE_GRAFANA_URL"] = fmt.Sprintf("http://localhost:%d", tr.GrafanaPort)
		}
	}
	in.userEnv(env, a.Decl.Name)
	return env
}

func (in *Input) chUser(role string) string { return in.M.L.Runtime() + "_" + role }

func (in *Input) chPassVar(role string) string {
	return strings.ToUpper(in.M.L.Runtime()) + "_CLICKHOUSE_" + role + "_PASSWORD"
}

// WorkerEnv is the environment of a project app (worker or prebuilt image).
func (in *Input) WorkerEnv(a *descriptor.AppModel) map[string]string {
	c := in.M.C
	d := a.Decl
	env := map[string]string{"MYCEL_KPI_URL": c.KPIBackend()}
	port := d.Port
	if port == 0 {
		port = 8090
	}
	env["PORT"] = fmt.Sprint(port)
	in.otel(env, d.Name, false)
	if c.Fabric.Temporal != nil && (d.Temporal != "" || d.Image == "") {
		hp := d.Temporal
		if hp == "" {
			hp = "temporal:7233"
		}
		env["TEMPORAL_HOSTPORT"] = hp
		env["TEMPORAL_NAMESPACE"] = in.temporalNS()
	}
	if d.DB != "" {
		env["DATABASE_URL"] = in.PG.URL(d.DB)
	}
	if in.M.HasToken("workflow_manager") && d.Image == "" {
		env["WORKFLOW_MANAGER_URL"] = "http://workflow-manager:7380"
	}
	in.userEnv(env, d.Name)
	return env
}

// RouteHost returns the front-door host label of a project app, if routed:
// its external_url host when it sits on the cluster domain, else its `host`.
func RouteHost(c *descriptor.Cluster, a *descriptor.App) string {
	if a.Cored() {
		return a.Host
	}
	if a.Host != "" {
		return a.Host
	}
	u := a.ExternalURL
	if u == "" {
		return ""
	}
	u = strings.TrimPrefix(strings.TrimPrefix(u, "http://"), "https://")
	host := strings.SplitN(strings.SplitN(u, "/", 2)[0], ":", 2)[0]
	suffix := "." + c.DomainOrDefault()
	if strings.HasSuffix(host, suffix) {
		return strings.TrimSuffix(host, suffix)
	}
	return ""
}

// SecretVars lists every ${VAR} the generated workloads need from .env or axon.
func (in *Input) SecretVars() []string {
	seen := map[string]bool{}
	var out []string
	add := func(env map[string]string) {
		for _, v := range env {
			for _, r := range refs(v) {
				if !seen[r] {
					seen[r] = true
					out = append(out, r)
				}
			}
		}
	}
	for _, a := range in.M.Apps {
		if a.Problem != "" {
			continue
		}
		if a.Decl.Cored() {
			add(in.CoreEnv(a))
			for _, mod := range a.Modules {
				add(in.ModuleEnv(a, mod))
			}
		} else {
			add(in.WorkerEnv(a))
		}
	}
	return out
}

func refs(s string) []string {
	var out []string
	for {
		i := strings.Index(s, "${")
		if i < 0 {
			break
		}
		j := strings.Index(s[i:], "}")
		if j < 0 {
			break
		}
		out = append(out, s[i+2:i+j])
		s = s[i+j+1:]
	}
	return out
}
